#include <stdio.h>
void swap(int *x, int *y)
{
  int t = *x;
  *x = *y;
  *y = t;
}
void sort3(int *a, int *b, int *c)
{
  if (*a > *b) swap(a, b);
  if (*a > *c) swap(a, c);
  if (*b > *c) swap(b, c);
}
int main(void)
{
  int x, y, z;
  scanf("%d%d%d", &x, &y, &z);
  sort3(&x, &y, &z);
  printf("%d %d %d\n", x, y, z);
  return 0;
}
